parameters.jsCode:
// Short WhatsApp for the owner when a Lumière flow fails. Plain words, no tech details (those go to the email).
// WhatsApp corto para la dueña cuando falla un flujo de Lumière. Palabras simples, sin detalle técnico (eso va en el correo).
// At most one per workflow every 30 min / Máximo uno por flujo cada 30 min (a failing schedule must not flood her phone).
const THROTTLE_MIN = 30;
const e = $('Error Trigger').first().json;
const res = $input.first().json || {};
if (res.error || !res.valueRanges) return [];          // Sheet unreadable -> only the email goes out
const rows = r => (r && r.values) || [];
const negocio = Object.fromEntries(rows(res.valueRanges[0]).slice(1).map(r => [r[0], r[1]]));
const duena = '+' + String(negocio.whatsapp_duena || negocio.whatsapp_equipo || '').replace(/\D/g, '');
if (duena.length < 12) return [];
const tz = negocio.zona_horaria || 'America/Phoenix';
const now = $now.setZone(tz);
const wfName = String((e.workflow || {}).name || '');
const execId = String((e.execution || {}).id || '');
const since = now.minus({ minutes: THROTTLE_MIN }).toFormat('yyyy-MM-dd HH:mm:ss');
// Eventos: evento_id, fecha, tipo, proyecto, lead_id, ref_id, detalle
const recent = rows(res.valueRanges[1]).slice(1).some(r => r[2] === 'error' && String(r[1]) >= since
  && String(r[6] || '').startsWith(wfName + ' ·') && String(r[5]) !== execId);
if (recent) return [];
const code = (wfName.match(/^P3[0-6]/) || ['P36'])[0];
const PROC = {
  es: { P30: 'la captura de leads de la web', P31: 'la atención por WhatsApp', P32: 'el seguimiento a leads', P33: 'los recordatorios de citas',
        P34: 'los mensajes después de la cita', P35: 'los mensajes de retoque y reactivación', P36: 'los reportes del sistema' },
  en: { P30: 'website lead capture', P31: 'WhatsApp client care', P32: 'lead follow-up', P33: 'appointment reminders',
        P34: 'post-visit messages', P35: 'touch-up and reactivation messages', P36: 'system reports' }
};
const lang = String(negocio.idioma_duena || 'en').startsWith('es') ? 'es' : 'en';
const hora = now.toFormat('HH:mm');
const mensaje = lang === 'es'
  ? `⚠️ Lumière: hubo una falla en ${PROC.es[code]} a las ${hora}. Tu soporte técnico ya recibió el detalle y lo está revisando. Si una clienta te escribe por algo de esto, atiéndela tú mientras tanto.`
  : `⚠️ Lumière: something failed in ${PROC.en[code]} at ${hora}. Your tech support already has the details and is on it. If a client contacts you about it, please handle her directly in the meantime.`;
// Inputs of P31e - Lumière Send WhatsApp (no client: logged with an empty lead_id)
return [{ json: { lead_id: '', whatsapp: duena, mensaje, rol: 'alerta_duena', origen: 'P36' } }];
